SELECT * FROM material_request WHERE user_id = #{userId} AND deleted = 0
AND status = #{status}
ORDER BY created_at DESC LIMIT #{offset}, #{size}

SELECT * FROM material_request WHERE deleted = 0
AND status = #{status}
AND user_id = #{applicantUserId}
AND applicant_group = #{applicantGroup}
ORDER BY created_at DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM material_request WHERE deleted = 0
AND status = #{status}
AND user_id = #{applicantUserId}
AND applicant_group = #{applicantGroup}

SELECT * FROM material_request WHERE deleted = 0
AND status IN ('APPROVED', 'REJECTED', 'FULFILLED', 'RECEIVED')
AND user_id = #{applicantUserId}
AND applicant_group = #{applicantGroup}
ORDER BY created_at DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM material_request WHERE deleted = 0
AND status IN ('APPROVED', 'REJECTED', 'FULFILLED', 'RECEIVED')
AND user_id = #{applicantUserId}
AND applicant_group = #{applicantGroup}

mapper.update:
UPDATE material_request SET status = #{status}, updated_at = #{reviewTime}
, first_reviewer_id = #{reviewerId}, first_review_time = #{reviewTime}
, first_reviewer_id = COALESCE(first_reviewer_id, #{reviewerId}), first_review_time = COALESCE(first_review_time, #{reviewTime}), second_reviewer_id = #{reviewerId}, second_review_time = #{reviewTime}
WHERE id = #{id}

mapper.select:
SELECT DISTINCT applicant_group FROM material_request WHERE applicant_group IS NOT NULL AND applicant_group != '' AND deleted = 0 AND status != 'DRAFT'
AND DATE(created_at) BETWEEN #{from} AND #{to}
ORDER BY applicant_group

SELECT user_id AS userId, MAX(applicant_name) AS applicantName FROM material_request WHERE deleted = 0 AND status != 'DRAFT'
AND DATE(created_at) BETWEEN #{from} AND #{to}
GROUP BY user_id ORDER BY MAX(applicant_name), user_id

SELECT r.id AS requestId, r.user_id AS userId, r.applicant_name AS applicantName, r.applicant_group AS applicantGroup, r.status AS status, DATE_FORMAT(r.created_at, '%Y-%m-%d %H:%i:%s') AS createdAt, DATE_FORMAT(r.fulfilled_at, '%Y-%m-%d %H:%i:%s') AS fulfilledAt, l.qty AS qty, l.fulfilled_qty AS fulfilledQty, l.snapshot_name AS itemName, l.spec_snapshot AS specSnapshot FROM material_request_line l JOIN material_request r ON l.request_id = r.id WHERE r.deleted = 0
AND l.item_id = #{itemId}
AND r.applicant_group = #{applicantGroup}
AND ( (l.fulfilled_qty > 0 AND r.fulfilled_at IS NOT NULL AND DATE(r.fulfilled_at) BETWEEN #{from} AND #{to}) OR (l.fulfilled_qty <= 0 AND DATE(r.created_at) BETWEEN #{from} AND #{to}) OR (l.fulfilled_qty > 0 AND r.fulfilled_at IS NULL AND DATE(r.created_at) BETWEEN #{from} AND #{to}) )
ORDER BY COALESCE(r.fulfilled_at, r.created_at) DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM material_request_line l JOIN material_request r ON l.request_id = r.id WHERE r.deleted = 0
AND l.item_id = #{itemId}
AND r.applicant_group = #{applicantGroup}
AND ( (l.fulfilled_qty > 0 AND r.fulfilled_at IS NOT NULL AND DATE(r.fulfilled_at) BETWEEN #{from} AND #{to}) OR (l.fulfilled_qty <= 0 AND DATE(r.created_at) BETWEEN #{from} AND #{to}) OR (l.fulfilled_qty > 0 AND r.fulfilled_at IS NULL AND DATE(r.created_at) BETWEEN #{from} AND #{to}) )

mapper.update:
UPDATE material_request
SET applicant_name = #{applicantName}, applicant_group = #{applicantGroup}
WHERE id = #{id}

mapper.select:
SELECT user_id, applicant_name, applicant_group, COUNT(*) AS total, COUNT(DISTINCT DATE(created_at)) AS active_days
FROM material_request WHERE deleted = 0 AND created_at BETWEEN #{from} AND #{to}
GROUP BY user_id, applicant_name, applicant_group ORDER BY total DESC

SELECT * FROM material_request WHERE deleted = 0
AND created_at BETWEEN #{from} AND #{to}
AND applicant_group = #{groupId}
ORDER BY created_at DESC LIMIT #{offset}, #{size}

SELECT COUNT(1) FROM material_request WHERE deleted = 0
AND created_at BETWEEN #{from} AND #{to}
AND applicant_group = #{groupId}

SELECT status, COUNT(*) AS count
FROM material_request
WHERE deleted = 0 AND DATE(created_at) BETWEEN #{from} AND #{to}
AND applicant_group = #{groupId}
GROUP BY status ORDER BY count DESC

SELECT
    SUM(CASE WHEN status IN ('APPROVED','FULFILLED','RECEIVED') THEN 1 ELSE 0 END) AS approved,
    SUM(CASE WHEN status = 'REJECTED' THEN 1 ELSE 0 END) AS rejected
FROM material_request
WHERE deleted = 0 AND DATE(created_at) BETWEEN #{from} AND #{to}
AND applicant_group = #{groupId}

SELECT l.item_id AS itemId, l.snapshot_name AS itemName,
       SUM(l.qty) AS totalQty, COUNT(DISTINCT l.request_id) AS requestCount
FROM material_request_line l JOIN material_request r ON l.request_id = r.id
WHERE r.deleted = 0 AND DATE(r.created_at) BETWEEN #{from} AND #{to}
AND r.applicant_group = #{groupId}
GROUP BY l.item_id, l.snapshot_name ORDER BY totalQty DESC LIMIT 30
